+'use client';
+
+import { useCallback, useRef, useEffect, useState } from 'react';
+import { useQuery } from '@tanstack/react-query';
+
+import { ImageObject, isImageObject } from '@/components/canvas/types';
+import { isImageSelection } from '@/hooks/use-selection-state';
+import { useFloatingTextareaPosition } from '@/hooks/use-floating-textarea-position';
+import { useImageGeneration } from '@/hooks/use-image-generation';
+import { useHistoryState } from '@/hooks/use-history-state';
+import { useCanvasTransformStore } from '@/store/canvas-transform-store';
+import { useImageDragStore } from '@/store/image-drag-store';
+import { useSelectionStore } from '@/store/selection-store';
+import { BaseModelWithRecommendedParameters } from '@/data/base-model';
+import { isSimpleCanvasModeEnabled } from '@/lib/feature-flags';
+import { BASE_MODEL_NANO_BANANA } from '@/constants/image';
+import { PLACEHOLDER_IMAGE_SRC } from '@/constants/canvas';
+import { createImagePayload } from '@/utils/canvas/image-payload-service';
+import useTokenBalanceData from '@/hooks/use-token-balance-data';
+import { AspectRatio } from '@/types/image-generation';
+import {
+  calculateDimensionsFromAspectRatio,
+  getSupportedAspectRatiosForModel
+} from '@/components/common/aspect-ratio-selector';
+
+import { FloatingTextarea } from './FloatingTextarea';
+
+/**
+ * Check if an image is an empty placeholder (no actual image content)
+ */
+function isEmptyPlaceholder(image: ImageObject): boolean {
+  const src = image.src;
+  if (!src) return true;
+  if (Array.isArray(src)) {
+    return (
+      src.length === 0 || src.every((s) => !s || s === PLACEHOLDER_IMAGE_SRC)
+    );
+  }
+  return src === '' || src === PLACEHOLDER_IMAGE_SRC;
+}
+
+const TEXTAREA_WIDTH = 320;
+
+export function FloatingTextareaContainer() {
+  const textareaContainerRef = useRef<HTMLDivElement>(null);
+  const [prompt, setPrompt] = useState('');
+  const [selectedBaseModel, setSelectedBaseModel] = useState(
+    BASE_MODEL_NANO_BANANA
+  );
+  const [selectedAspectRatio, setSelectedAspectRatio] = useState<
+    AspectRatio | undefined
+  >(undefined);
+  const simpleCanvasMode = isSimpleCanvasModeEnabled();
+
+  // Handle base model change - reset aspect ratio if current selection is invalid
+  const handleBaseModelChange = useCallback(
+    (newBaseModel: string) => {
+      setSelectedBaseModel(newBaseModel);
+
+      // Get supported ratios for the new model
+      const supportedRatios = getSupportedAspectRatiosForModel(newBaseModel);
+
+      // If no aspect ratio selected or current selection is still valid, do nothing
+      if (!selectedAspectRatio) return;
+
+      // If current aspect ratio is not supported by new model, reset to 1:1
+      if (
+        supportedRatios.length > 0 &&
+        !supportedRatios.includes(selectedAspectRatio)
+      ) {
+        setSelectedAspectRatio(AspectRatio.SQUARE);
+      } else if (supportedRatios.length === 0) {
+        // Model doesn't support aspect ratio selection at all
+        setSelectedAspectRatio(undefined);
+      }
+    },
+    [selectedAspectRatio]
+  );
+
+  // Fetch base models using React Query
+  const { data: baseModels, isLoading: isLoadingBaseModels } = useQuery({
+    queryKey: ['baseModels', simpleCanvasMode],
+    queryFn: async (): Promise<BaseModelWithRecommendedParameters[]> => {
+      const apiUrl = simpleCanvasMode
+        ? '/api/base-models?isSimpleCanvasMode=true'
+        : '/api/base-models';
+      const response = await fetch(apiUrl);
+      if (!response.ok) {
+        throw new Error(
+          'Network response was not ok when fetching base models'
+        );
+      }
+      return response.json();
+    }
+  });
+
+  // Selection state
+  const selection = useSelectionStore((state) => state.selection);
+  const firstSelected = selection.selected[0];
+
+  // Canvas objects and history state
+  const { canvasObjects, updateTempCanvasObjects, commitTempCanvasObjects } =
+    useHistoryState();
+
+  // Token balance for generation
+  const { tokenBalance = 0 } = useTokenBalanceData();
+
+  // Transform state for subscribing to changes
+  const position = useCanvasTransformStore((state) => state.position);
+  const scale = useCanvasTransformStore((state) => state.scale);
+
+  // Check if single image is selected
+  const isSingleImageSelected =
+    selection.selected.length === 1 && isImageSelection(firstSelected);
+
+  // Get the selected image object
+  const getSelectedImage = useCallback((): ImageObject | undefined => {
+    if (!isSingleImageSelected || !firstSelected) return undefined;
+
+    const obj = canvasObjects.find((o) => o.id === firstSelected.id);
+    return obj && isImageObject(obj) ? obj : undefined;
+  }, [isSingleImageSelected, firstSelected, canvasObjects]);
+
+  const selectedImage = getSelectedImage();
+
+  // Create callbacks for useImageGeneration
+  const handleAddImage = useCallback(
+    (imageObject: ImageObject) => {
+      // For floating textarea, we don't add new images - we update existing placeholder
+      // This callback is required by the hook but won't be used in our flow
+      updateTempCanvasObjects((prev) => [...prev, imageObject]);
+      commitTempCanvasObjects({
+        type: 'Added Image',
+        objectId: imageObject.id
+      });
+    },
+    [updateTempCanvasObjects, commitTempCanvasObjects]
+  );
+
+  const handleUpdateImage = useCallback(
+    (updatedImage: ImageObject) => {
+      updateTempCanvasObjects((prev) =>
+        prev.map((obj) => (obj.id === updatedImage.id ? updatedImage : obj))
+      );
+      commitTempCanvasObjects({
+        type: 'Generated Image',
+        objectId: updatedImage.id
+      });
+    },
+    [updateTempCanvasObjects, commitTempCanvasObjects]
+  );
+
+  // Use the main image generation hook
+  const { handleParallelGeneration, isGenerating } = useImageGeneration({
+    onAddImage: handleAddImage,
+    onUpdateImage: handleUpdateImage
+  });
+
+  // Position hook
+  const { updatePosition, updatePositionForImage } =
+    useFloatingTextareaPosition({
+      textareaContainerRef,
+      getSelectedImage,
+      textareaWidth: TEXTAREA_WIDTH,
+      offset: 60 // Vertical offset from bottom of image (pixels)
+    });
+
+  // Update position when selection changes
+  useEffect(() => {
+    if (selectedImage) {
+      updatePosition();
+    }
+  }, [selectedImage, updatePosition]);
+
+  // Update position when transform changes (zoom/pan)
+  useEffect(() => {
+    if (selectedImage) {
+      updatePosition();
+    }
+  }, [position.x, position.y, scale, selectedImage, updatePosition]);
+
+  // Subscribe to real-time drag/transform position updates
+  const draggingImageId = useImageDragStore((state) => state.draggingImageId);
+  const dragPosition = useImageDragStore((state) => state.dragPosition);
+  const dragDimensions = useImageDragStore((state) => state.dragDimensions);
+  const dragScale = useImageDragStore((state) => state.dragScale);
+
+  // Check if currently dragging this image
+  const isDraggingThisImage =
+    draggingImageId && selectedImage && draggingImageId === selectedImage.id;
+
+  // Update position when image position/size/scale changes (committed drag/resize/transform)
+  // Skip if currently dragging - let the drag effect handle it
+  useEffect(() => {
+    if (selectedImage && !isDraggingThisImage) {
+      updatePositionForImage(selectedImage);
+    }
+  }, [
+    selectedImage?.position.x,
+    selectedImage?.position.y,
+    selectedImage?.width,
+    selectedImage?.height,
+    selectedImage?.scaleX,
+    selectedImage?.scaleY,
+    selectedImage,
+    isDraggingThisImage,
+    updatePositionForImage
+  ]);
+
+  // Update position during drag/transform (real-time)
+  useEffect(() => {
+    // Only update if we're dragging/transforming the currently selected image
+    if (isDraggingThisImage && dragPosition && dragDimensions) {
+      // Create a temporary image object with the current drag/transform state
+      const tempImage: ImageObject = {
+        ...selectedImage,
+        position: dragPosition,
+        width: dragDimensions.width,
+        height: dragDimensions.height,
+        scaleX: dragScale?.scaleX ?? selectedImage.scaleX ?? 1,
+        scaleY: dragScale?.scaleY ?? selectedImage.scaleY ?? 1
+      };
+      updatePositionForImage(tempImage);
+    }
+  }, [
+    isDraggingThisImage,
+    dragPosition,
+    dragDimensions,
+    dragScale,
+    selectedImage,
+    updatePositionForImage
+  ]);
+
+  // Load existing prompt from image when selected
+  useEffect(() => {
+    if (selectedImage?.userPrompt) {
+      setPrompt(selectedImage.userPrompt);
+    } else {
+      setPrompt('');
+    }
+  }, [selectedImage?.id, selectedImage?.userPrompt]);
+
+  // Reset aspect ratio when selection changes
+  useEffect(() => {
+    setSelectedAspectRatio(undefined);
+  }, [selectedImage?.id]);
+
+  // Handle aspect ratio change - resize placeholder immediately
+  const handleAspectRatioChange = useCallback(
+    (aspectRatio: AspectRatio | undefined) => {
+      setSelectedAspectRatio(aspectRatio);
+
+      if (!aspectRatio || !selectedImage) return;
+
+      // Calculate new dimensions from aspect ratio
+      const { width: newWidth, height: newHeight } =
+        calculateDimensionsFromAspectRatio(
+          aspectRatio,
+          selectedImage.width,
+          selectedImage.height
+        );
+
+      // Calculate the center of the current image
+      const currentScaleX = selectedImage.scaleX ?? 1;
+      const currentScaleY = selectedImage.scaleY ?? 1;
+      const currentCenterX =
+        selectedImage.position.x + (selectedImage.width * currentScaleX) / 2;
+      const currentCenterY =
+        selectedImage.position.y + (selectedImage.height * currentScaleY) / 2;
+
+      // Calculate new position to maintain center
+      const newPosition = {
+        x: currentCenterX - newWidth / 2,
+        y: currentCenterY - newHeight / 2
+      };
+
+      // Update the placeholder with new dimensions
+      const updatedImage: ImageObject = {
+        ...selectedImage,
+        width: newWidth,
+        height: newHeight,
+        position: newPosition,
+        // Reset scale since we're changing the base dimensions
+        scaleX: 1,
+        scaleY: 1
+      };
+
+      updateTempCanvasObjects((prev) =>
+        prev.map((obj) => (obj.id === updatedImage.id ? updatedImage : obj))
+      );
+      commitTempCanvasObjects({
+        type: 'Resized Image',
+        objectId: updatedImage.id
+      });
+    },
+    [selectedImage, updateTempCanvasObjects, commitTempCanvasObjects]
+  );
+
+  // Handle generation submission
+  const handleSubmit = useCallback(async () => {
+    if (!prompt.trim() || !selectedImage) return;
+
+    // Build minimal payload for T2I generation
+    const payload = createImagePayload({
+      baseModel: selectedBaseModel,
+      seed: Math.floor(Math.random() * 1000000000),
+      width: selectedImage.width,
+      height: selectedImage.height,
+      prompt,
+      selectedCharacter: null,
+      numberOfImages: 1,
+      // Use defaults for optional params
+      steps: 20,
+      loras: [],
+      cfgScale: 7,
+      clipSkip: 1,
+      negativePrompt: '',
+      denoisingStrength: 1,
+      samplerName: 'euler',
+      scheduler: 'simple'
+    });
+
+    await handleParallelGeneration({
+      panelId: selectedImage.parentId ?? null,
+      prompt,
+      width: selectedImage.width,
+      height: selectedImage.height,
+      position: selectedImage.position,
+      baseModel: selectedBaseModel,
+      payload,
+      target: { type: 'image', imageToReplace: selectedImage },
+      numberOfImages: 1,
+      originalTokenCount: tokenBalance,
+      aspectRatio: selectedAspectRatio
+    });
+  }, [
+    prompt,
+    selectedImage,
+    selectedBaseModel,
+    selectedAspectRatio,
+    handleParallelGeneration,
+    tokenBalance
+  ]);
+
+  // Only show floating textarea for empty placeholder images that are not generating
+  const visible =
+    isSingleImageSelected &&
+    !!selectedImage &&
+    isEmptyPlaceholder(selectedImage) &&
+    !selectedImage.isGenerating;
+
+  // Get supported aspect ratios based on selected model
+  const supportedAspectRatios =
+    getSupportedAspectRatiosForModel(selectedBaseModel);
+
+  // Get the cost per image for the selected model
+  const currentBaseModel = baseModels?.find(
+    (model) => model.fileName === selectedBaseModel
+  );
+  const costPerImage = currentBaseModel?.tokenCost ?? undefined;
+
+  return (
+    <FloatingTextarea
+      ref={textareaContainerRef}
+      value={prompt}
+      onChange={setPrompt}
+      onSubmit={handleSubmit}
+      visible={visible}
+      width={TEXTAREA_WIDTH}
+      isGenerating={isGenerating}
+      baseModels={baseModels ?? []}
+      selectedBaseModel={selectedBaseModel}
+      onBaseModelChange={handleBaseModelChange}
+      isLoadingBaseModels={isLoadingBaseModels}
+      selectedAspectRatio={selectedAspectRatio}
+      onAspectRatioChange={handleAspectRatioChange}
+      supportedAspectRatios={supportedAspectRatios}
+      costPerImage={costPerImage}
+    />
+  );
+}
