@@ -0,0 +1,308 @@
+'use client';
+
+import { useTranslations } from 'next-intl';
+
+import { Combobox, ComboboxOption } from '@/components/ui/comboBox';
+import { AspectRatio } from '@/types/image-generation';
+import { isGeminiModel, isGemini25Plus, isGptModel } from '@/constants/image';
+
+// Re-export for backward compatibility
+export { AspectRatio } from '@/types/image-generation';
+/** @deprecated Use AspectRatio instead */
+export { GeminiAspectRatio } from '@/types/image-generation';
+
+/**
+ * Parse aspectRatio string to width/height ratio
+ * @param aspectRatio e.g. "1:1", "16:9"
+ * @returns { width: number, height: number }
+ */
+function parseAspectRatio(aspectRatio: string): {
+  width: number;
+  height: number;
+} {
+  const [width, height] = aspectRatio.split(':').map(Number);
+  return { width, height };
+}
+
+/**
+ * Generate SVG polygon preview
+ * @param aspectRatio e.g. "1:1", "16:9"
+ * @param size Preview container size (width/height)
+ * @returns SVG polygon points string and stroke width
+ */
+function getAspectRatioPreview(
+  aspectRatio: string,
+  size: number = 24
+): { points: string; strokeWidth: number } {
+  const { width, height } = parseAspectRatio(aspectRatio);
+  const ratio = width / height;
+
+  // Preview drawing area (with padding)
+  const padding = 2;
+  const drawSize = size - padding * 2;
+
+  let previewWidth: number;
+  let previewHeight: number;
+
+  if (ratio > 1) {
+    // Landscape
+    previewWidth = drawSize;
+    previewHeight = drawSize / ratio;
+  } else if (ratio < 1) {
+    // Portrait
+    previewWidth = drawSize * ratio;
+    previewHeight = drawSize;
+  } else {
+    // Square
+    previewWidth = drawSize;
+    previewHeight = drawSize;
+  }
+
+  // Calculate center position
+  const offsetX = (size - previewWidth) / 2;
+  const offsetY = (size - previewHeight) / 2;
+
+  // Generate rectangle polygon points
+  const x1 = offsetX;
+  const y1 = offsetY;
+  const x2 = offsetX + previewWidth;
+  const y2 = offsetY;
+  const x3 = offsetX + previewWidth;
+  const y3 = offsetY + previewHeight;
+  const x4 = offsetX;
+  const y4 = offsetY + previewHeight;
+
+  const points = `${x1},${y1} ${x2},${y2} ${x3},${y3} ${x4},${y4}`;
+
+  // Dynamically adjust stroke width based on preview size
+  const minDimension = Math.min(previewWidth, previewHeight);
+  const strokeWidth = minDimension < 8 ? 0.5 : minDimension < 16 ? 0.75 : 1;
+
+  return { points, strokeWidth };
+}
+
+/**
+ * AspectRatio preview component
+ */
+export function AspectRatioPreview({ aspectRatio }: { aspectRatio: string }) {
+  const { points, strokeWidth } = getAspectRatioPreview(aspectRatio, 24);
+
+  return (
+    <svg
+      width="24"
+      height="24"
+      viewBox="0 0 24 24"
+      className="flex-shrink-0"
+      style={{ minWidth: '24px' }}
+    >
+      <polygon
+        points={points}
+        fill="currentColor"
+        fillOpacity="0.1"
+        stroke="currentColor"
+        strokeWidth={strokeWidth}
+        className="text-primary"
+      />
+    </svg>
+  );
+}
+
+/**
+ * All available aspectRatio options (only ratio numbers, no i18n needed)
+ */
+export const ASPECT_RATIO_OPTIONS: Record<AspectRatio, string> = {
+  [AspectRatio.SQUARE]: '1:1',
+  [AspectRatio.PORTRAIT_2_3]: '2:3',
+  [AspectRatio.LANDSCAPE_3_2]: '3:2',
+  [AspectRatio.PORTRAIT_3_4]: '3:4',
+  [AspectRatio.LANDSCAPE_4_3]: '4:3',
+  [AspectRatio.PORTRAIT_4_5]: '4:5',
+  [AspectRatio.LANDSCAPE_5_4]: '5:4',
+  [AspectRatio.MOBILE_9_16]: '9:16',
+  [AspectRatio.WIDESCREEN_16_9]: '16:9',
+  [AspectRatio.ULTRAWIDE_21_9]: '21:9'
+};
+
+/**
+ * Convert aspectRatio options to ComboboxOption array
+ * @param supportedAspectRatios Supported aspect ratio options, returns all if not provided
+ */
+export function getAspectRatioOptions(
+  supportedAspectRatios?: AspectRatio[]
+): ComboboxOption[] {
+  return supportedAspectRatios && supportedAspectRatios.length > 0
+    ? supportedAspectRatios.map((ratio) => ({
+        label: ASPECT_RATIO_OPTIONS[ratio],
+        value: ratio
+      }))
+    : Object.entries(ASPECT_RATIO_OPTIONS).map(([value, label]) => ({
+        label,
+        value
+      }));
+}
+
+export interface AspectRatioSelectorProps {
+  /**
+   * Currently selected aspect ratio
+   */
+  value?: AspectRatio;
+
+  /**
+   * Callback when selection changes
+   */
+  onValueChange: (value: AspectRatio | undefined) => void;
+
+  /**
+   * Supported aspect ratio options
+   * If not provided, all available options are shown
+   */
+  supportedAspectRatios?: AspectRatio[];
+
+  /**
+   * Placeholder text
+   */
+  placeholder?: string;
+
+  /**
+   * Whether disabled
+   */
+  disabled?: boolean;
+
+  /**
+   * Custom className
+   */
+  className?: string;
+}
+
+/**
+ * Aspect ratio selector component (single select)
+ * Provides a dropdown for users to select an aspect ratio
+ */
+export function AspectRatioSelector({
+  value,
+  onValueChange,
+  supportedAspectRatios,
+  placeholder,
+  className
+}: AspectRatioSelectorProps) {
+  const t = useTranslations('common.aspectRatioSelector');
+
+  // Filter options based on supportedAspectRatios
+  // If not specified, show all options
+  const availableOptions = getAspectRatioOptions(supportedAspectRatios);
+
+  // Custom option rendering with preview and ratio
+  const renderOption = (option: ComboboxOption) => {
+    return (
+      <span className="flex items-center gap-3">
+        <AspectRatioPreview aspectRatio={option.label} />
+        <span className="text-sm font-medium">{option.label}</span>
+      </span>
+    );
+  };
+
+  return (
+    <Combobox
+      options={availableOptions}
+      value={value || ''}
+      onValueChange={(newValue) => {
+        onValueChange(newValue ? (newValue as AspectRatio) : undefined);
+      }}
+      placeholder={placeholder || t('selectAspectRatio')}
+      className={className}
+      renderOption={renderOption}
+    />
+  );
+}
+
+/**
+ * GPT model supported aspect ratios
+ */
+const GPT_ASPECT_RATIOS: AspectRatio[] = [
+  AspectRatio.SQUARE, // 1:1
+  AspectRatio.LANDSCAPE_3_2, // 3:2
+  AspectRatio.PORTRAIT_2_3 // 2:3
+];
+
+/**
+ * Default aspect ratios for ComfyUI and other models
+ */
+const DEFAULT_ASPECT_RATIOS: AspectRatio[] = [
+  AspectRatio.SQUARE, // 1:1
+  AspectRatio.LANDSCAPE_3_2, // 3:2
+  AspectRatio.PORTRAIT_2_3, // 2:3
+  AspectRatio.LANDSCAPE_4_3, // 4:3
+  AspectRatio.PORTRAIT_3_4, // 3:4
+  AspectRatio.WIDESCREEN_16_9, // 16:9
+  AspectRatio.MOBILE_9_16, // 9:16
+  AspectRatio.ULTRAWIDE_21_9 // 21:9
+];
+
+/**
+ * Gemini 2.5+ supported aspect ratios (all ratios)
+ */
+const ALL_ASPECT_RATIOS: AspectRatio[] = Object.values(
+  AspectRatio
+) as AspectRatio[];
+
+/**
+ * Get supported aspect ratios based on model type
+ * @param baseModel - The model file name/identifier
+ * @returns Array of supported AspectRatio values, or empty array if not supported
+ */
+export function getSupportedAspectRatiosForModel(
+  baseModel: string
+): AspectRatio[] {
+  // Gemini models before 2.5 don't support aspect ratio selection
+  if (isGeminiModel(baseModel) && !isGemini25Plus(baseModel)) {
+    return [];
+  }
+
+  // Gemini 2.5+ supports all aspect ratios
+  if (isGemini25Plus(baseModel)) {
+    return ALL_ASPECT_RATIOS;
+  }
+
+  // GPT models have limited aspect ratio support
+  if (isGptModel(baseModel)) {
+    return GPT_ASPECT_RATIOS;
+  }
+
+  // Default: ComfyUI and other models
+  return DEFAULT_ASPECT_RATIOS;
+}
+
+/**
+ * Get supported aspect ratio strings for DimensionSelect filter
+ * @param baseModel - The model file name/identifier
+ * @returns Array of aspect ratio strings like ['1:1', '3:2', '2:3'], or empty array if not supported
+ */
+export function getSupportedAspectRatioStringsForModel(
+  baseModel: string
+): string[] {
+  const ratios = getSupportedAspectRatiosForModel(baseModel);
+  return ratios.map((ratio) => ASPECT_RATIO_OPTIONS[ratio]);
+}
+
+/**
+ * Calculate new dimensions from aspect ratio
+ * Maintains similar area while changing to the new ratio
+ */
+export function calculateDimensionsFromAspectRatio(
+  aspectRatio: AspectRatio,
+  currentWidth: number,
+  currentHeight: number
+): { width: number; height: number } {
+  // Parse ratio like "16:9" to width/height multipliers
+  const [ratioW, ratioH] = aspectRatio.split(':').map(Number);
+
+  // Calculate current area and target ratio
+  const currentArea = currentWidth * currentHeight;
+  const targetRatio = ratioW / ratioH;
+
+  // Calculate new dimensions maintaining similar area
+  const newHeight = Math.sqrt(currentArea / targetRatio);
+  const newWidth = newHeight * targetRatio;
+
+  return { width: Math.round(newWidth), height: Math.round(newHeight) };
+}
