+'use client';
+
+import { forwardRef, memo, useMemo } from 'react';
+
+import { Textarea } from '@/components/ui/textarea';
+import { CanvasGenerateButton } from '@/components/canvas/canvas-generate-button';
+import {
+  Select,
+  SelectContent,
+  SelectItem,
+  SelectTrigger,
+  SelectValue
+} from '@/components/ui/select';
+import { cn } from '@/lib/utils';
+import { BaseModelWithRecommendedParameters } from '@/data/base-model';
+import { AspectRatio } from '@/types/image-generation';
+import {
+  AspectRatioPreview,
+  ASPECT_RATIO_OPTIONS
+} from '@/components/common/aspect-ratio-selector';
+
+interface FloatingTextareaProps {
+  value: string;
+  onChange: (value: string) => void;
+  onSubmit: () => void;
+  visible: boolean;
+  width?: number;
+  isGenerating?: boolean;
+  placeholder?: string;
+  baseModels?: BaseModelWithRecommendedParameters[];
+  selectedBaseModel?: string;
+  onBaseModelChange?: (baseModel: string) => void;
+  isLoadingBaseModels?: boolean;
+  selectedAspectRatio?: AspectRatio;
+  onAspectRatioChange?: (aspectRatio: AspectRatio | undefined) => void;
+  supportedAspectRatios?: AspectRatio[];
+  /** Token cost per image for the selected model */
+  costPerImage?: number;
+}
+
+export const FloatingTextarea = memo(
+  forwardRef<HTMLDivElement, FloatingTextareaProps>(function FloatingTextarea(
+    {
+      value,
+      onChange,
+      onSubmit,
+      visible,
+      width = 480,
+      isGenerating = false,
+      placeholder = 'Describe the image you want to generate...',
+      baseModels = [],
+      selectedBaseModel,
+      onBaseModelChange,
+      isLoadingBaseModels = false,
+      selectedAspectRatio,
+      onAspectRatioChange,
+      supportedAspectRatios = [],
+      costPerImage
+    },
+    ref
+  ) {
+    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
+      if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
+        e.preventDefault();
+        onSubmit();
+      }
+    };
+
+    // Get aspect ratio options filtered by supported ratios
+    const aspectRatioOptions = useMemo(() => {
+      const allOptions = Object.entries(ASPECT_RATIO_OPTIONS) as [
+        AspectRatio,
+        string
+      ][];
+
+      // If no supported ratios provided, return all options (for display when disabled)
+      if (supportedAspectRatios.length === 0) {
+        return allOptions;
+      }
+
+      // Filter to only supported ratios
+      return allOptions.filter(([ratioKey]) =>
+        supportedAspectRatios.includes(ratioKey)
+      );
+    }, [supportedAspectRatios]);
+
+    // Show aspect ratio selector, but disable if model doesn't support it
+    const showAspectRatioSelector = !!onAspectRatioChange;
+    const isAspectRatioDisabled =
+      isGenerating || supportedAspectRatios.length === 0;
+
+    if (!visible) return null;
+
+    return (
+      <div
+        ref={ref}
+        className={cn(
+          'fixed z-20 flex flex-col gap-2 p-3 rounded-lg',
+          'border border-gray-200 shadow-lg bg-white',
+          'transition-opacity duration-150',
+          '-translate-x-1/2' // Anchor from top-center instead of top-left
+        )}
+        style={{
+          width: `${width}px`,
+          left: '-9999px',
+          top: '-9999px'
+        }}
+      >
+        <Textarea
+          value={value}
+          onChange={(e) => onChange(e.target.value)}
+          onKeyDown={handleKeyDown}
+          placeholder={placeholder}
+          disabled={isGenerating}
+          className="resize-none text-sm min-h-[60px] max-h-[120px]"
+          rows={2}
+        />
+        <div className="flex justify-between items-center gap-2">
+          <div className="flex gap-1 flex-1 min-w-0">
+            {baseModels.length > 0 && onBaseModelChange && selectedBaseModel ? (
+              <Select
+                value={selectedBaseModel}
+                onValueChange={onBaseModelChange}
+                disabled={isGenerating || isLoadingBaseModels}
+              >
+                <SelectTrigger className="flex-1 min-w-0 h-8 text-xs">
+                  <SelectValue placeholder="Select model" />
+                </SelectTrigger>
+                <SelectContent>
+                  {baseModels
+                    .filter((model) => model.fileName)
+                    .map((model) => (
+                      <SelectItem
+                        key={model.fileName}
+                        value={model.fileName!}
+                        className="text-xs"
+                      >
+                        {model.name}
+                      </SelectItem>
+                    ))}
+                </SelectContent>
+              </Select>
+            ) : (
+              <span className="text-xs text-gray-400">Cmd/Ctrl + Enter</span>
+            )}
+            {showAspectRatioSelector && (
+              <Select
+                value={selectedAspectRatio || '1:1'}
+                onValueChange={(value) =>
+                  onAspectRatioChange(
+                    value ? (value as AspectRatio) : undefined
+                  )
+                }
+                disabled={isAspectRatioDisabled}
+              >
+                <SelectTrigger className="w-[72px] h-8 text-xs flex-shrink-0">
+                  <SelectValue placeholder="Ratio">
+                    {selectedAspectRatio && (
+                      <span className="flex items-center gap-1">
+                        <AspectRatioPreview aspectRatio={selectedAspectRatio} />
+                      </span>
+                    )}
+                  </SelectValue>
+                </SelectTrigger>
+                <SelectContent>
+                  {aspectRatioOptions.map(([ratioKey, ratioLabel]) => (
+                    <SelectItem
+                      key={ratioKey}
+                      value={ratioKey}
+                      className="text-xs"
+                    >
+                      <span className="flex items-center gap-2">
+                        <AspectRatioPreview aspectRatio={ratioLabel} />
+                        <span>{ratioLabel}</span>
+                      </span>
+                    </SelectItem>
+                  ))}
+                </SelectContent>
+              </Select>
+            )}
+          </div>
+          <CanvasGenerateButton
+            size="sm"
+            handleGenerate={onSubmit}
+            isGenerating={isGenerating}
+            disabled={!value.trim()}
+            costPerImage={costPerImage}
+            labelText="Generate"
+            className="flex-shrink-0 w-auto"
+          />
+        </div>
+      </div>
+    );
+  })
+);
